create extension if not exists pgcrypto;
create type public.app_role as enum ('super_admin','owner','hr_manager','branch_manager','accountant','supervisor','employee');
create type public.attendance_event_type as enum ('check_in','check_out');
create type public.record_status as enum ('active','inactive','suspended');
create table public.branches (id uuid primary key default gen_random_uuid(), name text not null, code text unique not null, address text, logo_url text, latitude numeric(10,7), longitude numeric(10,7), geofence_radius_m integer not null default 150 check(geofence_radius_m between 30 and 1000), active boolean not null default true, created_at timestamptz not null default now());
create table public.user_roles (user_id uuid primary key references auth.users(id) on delete cascade, role public.app_role not null default 'employee', branch_id uuid references public.branches(id), created_at timestamptz not null default now());
create table public.employees (id uuid primary key default gen_random_uuid(), auth_user_id uuid unique references auth.users(id) on delete set null, employee_code text unique not null, branch_id uuid not null references public.branches(id), full_name text not null, phone text, email text, position text, employment_type text not null default 'monthly' check(employment_type in ('monthly','daily','hourly')), base_monthly numeric(12,2) not null default 0, hourly_rate numeric(12,2), service_charge_default numeric(12,2) not null default 0, commission_default numeric(12,2) not null default 0, hire_date date, status public.record_status not null default 'active', created_at timestamptz not null default now());
create table public.biometric_consents (id uuid primary key default gen_random_uuid(), employee_id uuid not null references public.employees(id) on delete cascade, status text not null check(status in ('active','withdrawn','expired')), consent_text_version text not null, consented_at timestamptz not null default now(), expires_at timestamptz, withdrawn_at timestamptz, created_at timestamptz not null default now());
create table public.face_enrollments (employee_id uuid primary key references public.employees(id) on delete cascade, provider_reference text not null, status text not null check(status in ('active','revoked')), created_by uuid references auth.users(id), created_at timestamptz not null default now(), revoked_at timestamptz);
create table public.shifts (id uuid primary key default gen_random_uuid(), branch_id uuid not null references public.branches(id) on delete cascade, name text not null, starts_at time not null, ends_at time not null, break_minutes integer not null default 0, active boolean not null default true);
create table public.shift_assignments (id uuid primary key default gen_random_uuid(), employee_id uuid not null references public.employees(id) on delete cascade, shift_id uuid not null references public.shifts(id), work_date date not null, status text not null default 'scheduled' check(status in ('scheduled','approved','cancelled')), unique(employee_id,work_date));
create table public.attendance_events (id uuid primary key default gen_random_uuid(), employee_id uuid not null references public.employees(id), branch_id uuid not null references public.branches(id), event_type public.attendance_event_type not null, occurred_at timestamptz not null, latitude numeric(10,7) not null, longitude numeric(10,7) not null, gps_distance_m integer, verification_method text not null, face_provider_reference text, created_at timestamptz not null default now());
create table public.leave_requests (id uuid primary key default gen_random_uuid(), employee_id uuid not null references public.employees(id), leave_type text not null, start_date date not null, end_date date not null, reason text, status text not null default 'pending' check(status in ('pending','approved','rejected')), reviewed_by uuid references auth.users(id), created_at timestamptz not null default now());
create table public.payroll_runs (id uuid primary key default gen_random_uuid(), branch_id uuid not null references public.branches(id), period_start date not null, period_end date not null, status text not null default 'draft' check(status in ('draft','approved','paid','void')), created_by uuid references auth.users(id), approved_by uuid references auth.users(id), created_at timestamptz not null default now(), check(period_end >= period_start));
create table public.payroll_items (id uuid primary key default gen_random_uuid(), payroll_run_id uuid not null references public.payroll_runs(id) on delete cascade, employee_id uuid not null references public.employees(id), branch_id uuid not null references public.branches(id), period_start date not null, period_end date not null, regular_pay numeric(12,2) not null default 0, overtime_pay numeric(12,2) not null default 0, total_earnings numeric(12,2) not null default 0, total_deductions numeric(12,2) not null default 0, net_pay numeric(12,2) not null default 0, status text not null default 'draft', created_at timestamptz not null default now(), unique(payroll_run_id,employee_id));
create table public.audit_logs (id bigint generated always as identity primary key, actor_id uuid references auth.users(id), action text not null, entity_table text not null, entity_id text, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
alter table public.branches enable row level security; alter table public.user_roles enable row level security; alter table public.employees enable row level security; alter table public.biometric_consents enable row level security; alter table public.face_enrollments enable row level security; alter table public.shifts enable row level security; alter table public.shift_assignments enable row level security; alter table public.attendance_events enable row level security; alter table public.leave_requests enable row level security; alter table public.payroll_runs enable row level security; alter table public.payroll_items enable row level security; alter table public.audit_logs enable row level security;
create or replace function public.current_app_role() returns public.app_role language sql stable security definer set search_path=public as $$ select role from public.user_roles where user_id=auth.uid() $$;
create policy "users read own role" on public.user_roles for select using (user_id=auth.uid());
create policy "employees read self" on public.employees for select using (auth_user_id=auth.uid());
create policy "employees read branch managers" on public.employees for select using (exists(select 1 from public.user_roles r where r.user_id=auth.uid() and r.branch_id=employees.branch_id and r.role in ('owner','super_admin','hr_manager','branch_manager','accountant','supervisor')));
create policy "employee read own attendance" on public.attendance_events for select using (exists(select 1 from public.employees e where e.id=employee_id and e.auth_user_id=auth.uid()));
create policy "employee read own payslip" on public.payroll_items for select using (exists(select 1 from public.employees e where e.id=employee_id and e.auth_user_id=auth.uid()));
create policy "employee read own leave" on public.leave_requests for select using (exists(select 1 from public.employees e where e.id=employee_id and e.auth_user_id=auth.uid()));
insert into public.branches(name,code,geofence_radius_m) values ('SOMETIME Main Branch','STM-MAIN',150) on conflict(code) do nothing;
